(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["principles-of-diagnostic-medicine-i-exam-4"]={"title":"Principles of Diagnostic Medicine I Exam 4","sections":[{"id":"scope","title":"How This Exam Is Written","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-landmarks","title":"Landmarks You Can Feel (Lecture 17)","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-normal-film","title":"The Normal Chest Film","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l17-airway","title":"Upper Airway Films","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"},{"id":"l17-technique","title":"Is It the Film or the Patient?","style":"--acc:#2f5d62;--acc-bg:#e2e8e9;--acc-zebra:#f0f4f4;--acc-ink:#25494c"},{"id":"l17-modalities","title":"Choosing the Study","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-safety","title":"Contraindications and Cautions","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l17-ct","title":"Reading Computed Tomography","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"},{"id":"l17-patterns","title":"The Five Patterns","style":"--acc:#2f5d62;--acc-bg:#e2e8e9;--acc-zebra:#f0f4f4;--acc-ink:#25494c"}],"rows":[{"t":"Reference ranges are GIVEN","d":"“I'm not going to just throw a random number at you” — a creatinine or any value in a stem comes with the range that reads it.","s":0},{"t":"Tests over diagnoses","d":"“More related to the tests themselves”: which study, why, its cautions, and what normal looks like on it.","s":0},{"t":"Next-best-test","d":"In imaging it is a study: radiograph first; angiogram first for a suspected pulmonary embolism; computed tomography when the radiograph is inconclusive; ventilation/perfusion when contrast can't be given.","s":0},{"t":"Images in play","d":"Expect a film or a slice with the vignette. Technique first, then structures, then the pattern.","s":0},{"t":"★ Sternal angle","d":"The manubriosternal joint communicates with the SECOND rib: find the second rib for procedures, then palpate down and count.","s":1},{"t":"★ Nipple line","d":"Corresponds to the FIFTH intercostal space.","s":1},{"t":"Fifth rib","d":"Below the base of the fifth rib are the INFERIOR lobes; above it, the SUPERIOR lobes.","s":1},{"t":"Jugular notch","d":"Deep to it is the TRACHEA.","s":1},{"t":"Larynx","d":"C3 to C6 (the slide; the recording's \"C9\" does not exist). Cricothyroid ligament about 1 centimeter below the laryngeal prominence.","s":1},{"t":"Neck triangles","d":"POSTERIOR triangle: subclavian vein and lung apices. CAROTID triangle: bifurcation of the common carotid. The sternocleidomastoid divides anterior from posterior.","s":1},{"t":"First line","d":"Chest radiographs are the most common radiologic study (radiographs = 75% of images ordered) and almost always FIRST for a pulmonary or cardiac complaint; pain and shortness of breath.","s":2},{"t":"★ Posteroanterior vs anteroposterior","d":"POSTEROANTERIOR = ambulatory, standing. ANTEROPOSTERIOR = supine, HEART MAGNIFIED: do not call it enlarged on that view alone.","s":2},{"t":"★ Aortic knob","d":"The rounded bulge at the top of the left mediastinal border (the aortic arch); pulmonary artery just below, then the left hilum.","s":2},{"t":"★ Costophrenic angles","d":"Sharp Vs where each hemidiaphragm meets the chest wall: \"nice and sharp\" is normal. Gastric bubble under the left hemidiaphragm.","s":2},{"t":"★ Heart size","d":"No more than HALF the posteroanterior span of the chest; one third right of the midline, two thirds left.","s":2},{"t":"★ Hila","d":"Bisect the chest; mostly pulmonary arteries and veins (plus fat, nodes, bronchial walls); LEFT slightly HIGHER; concave, similar size and density.","s":2},{"t":"★ Trachea","d":"Smooth radiopaque border, radiolucent inside, MIDLINE.","s":2},{"t":"The rest of the read","d":"Lungs radiolucent; retrosternal and retrocardiac spaces; only pulmonary arteries and veins as vascular markings; each rib one at a time, both sides; spinous processes midline. Lateral film: thoracic spine has a posterior arch.","s":2},{"t":"Indications","d":"Muffled voice; stridor (wheeze heard from the mouth without a stethoscope); suspected sinus infection; anterior neck pain.","s":3},{"t":"Water's view","d":"Maxillary and frontal sinuses, 45 degrees to the orbitomeatal line. For sinusitis: not really needed, but can confirm it and possibly REDUCE ANTIBIOTIC use.","s":3},{"t":"★ Lateral soft-tissue neck","d":"Trachea = the dark, patent, radiolucent air column. The esophagus sits in the RETROTRACHEAL space and shows NO air: collapsed = NORMAL when not eating.","s":3},{"t":"Bones on the neck film","d":"Slight ANTERIOR curve (cervical lordosis). The body below C7 is partly hidden by the FIRST RIB.","s":3},{"t":"How to read it","d":"Superior to inferior, left to right; airways dark; sinuses air-filled; bones continuous; always symmetry.","s":3},{"t":"Good exposure","d":"Vessels to at least the PERIPHERAL THIRD; paraspinous margins; left hemidiaphragm visible behind the heart.","s":4},{"t":"Overexposed","d":"DARK: thoracic spine, mediastinum, retrocardiac areas and nasogastric/endotracheal tubes show through.","s":4},{"t":"Underexposed","d":"WHITE: small vessels, NO spine and NO mediastinal anatomy.","s":4},{"t":"Inspiration","d":"Domes to the TENTH posterior rib standing (eighth to tenth seated or lying). Few ribs above the diaphragm = poor effort.","s":4},{"t":"★ Rotation","d":"Spinous processes to the clavicle borders. Do NOT use the tracheal shadow (a tube looks the same rotated).","s":4},{"t":"The checklist","d":"Trachea midline or deviated; lungs shadowing or lucency; vessels enlarged; HILA masses or lymphadenopathy; mediastinum width or mass; PLEURA effusion, thickening, calcification; BONES lesions or fractures; soft tissues: don't miss a mastectomy.","s":4},{"t":"Computed tomography first?","d":"ONLY for a suspected pulmonary embolism: the computed tomography ANGIOGRAM. Everything else starts with the radiograph.","s":5},{"t":"Radiograph indications","d":"Chest pain, dyspnea, cough over 6 WEEKS unexplained, unexplained weight loss in any chronic SMOKER, hemoptysis, adventitious sounds, support hardware (lines, tubes, pacemaker).","s":5},{"t":"Computed tomography","d":"Most common reason: an INCONCLUSIVE radiograph with a continuing problem. Also embolism, trauma, chronic obstructive pulmonary and interstitial lung disease, BONE (rib and spine fractures), cancer screening. Head and neck: retropharyngeal abscess or foreign body the radiograph missed.","s":5},{"t":"Contrast is for","d":"VASCULAR pathology (embolism, dissection, aneurysm), focal lesions, the -itis conditions (magnetic resonance superior for vasculitis), METASTASES to lymph nodes.","s":5},{"t":"Ultrasound","d":"Almost exclusively TRAUMA: collapsed lung or fluid (extended focused assessment with sonography for trauma); procedures; NO contraindications. Ribs cast shadows.","s":5},{"t":"★ Ventilation/perfusion","d":"For pulmonary embolism when the angiogram can't be done (CONTRAST ALLERGY); INFERIOR to the angiogram. Ventilation: INHALED technetium-99m. Perfusion: INJECTED technetium-99m macroaggregated albumin. Result: low, medium or high probability.","s":5},{"t":"Positron emission tomography","d":"Higher resolution and sensitivity than single-photon, more cost; usually secondary to the radiograph; mostly for METASTASES; now done with computed tomography for a much CLEARER image.","s":5},{"t":"Magnetic resonance","d":"King of soft tissue, but the lungs' anatomy makes computed tomography first. Used for a mass INCONCLUSIVE on computed tomography, patients who can't have it, vasculopathy (second choice); SUPERIOR to the angiogram for INTRAMURAL HEMATOMA. Inflammation: dark T1, bright T2.","s":5},{"t":"Who reads it","d":"The radiologist gives the official read; the clinician's read is often just for the answer.","s":5},{"t":"★ Radiographs","d":"NO true contraindications. Lifetime limit 100 millisieverts = about 10,000 chest radiographs or 25 chest computed tomography scans.","s":6},{"t":"★ Pregnancy test","d":"\"Always, always, always\": beta human chorionic gonadotropin (urine or blood) on every female of childbearing age. Pregnancy is NOT an absolute contraindication; emergent imaging is done, even with contrast.","s":6},{"t":"Lead shielding","d":"Everything not being filmed, especially thyroid, ovaries, testes, breasts, fetus.","s":6},{"t":"★ Contrast cautions","d":"Anaphylaxis to medicines; ★ SHELLFISH anaphylaxis not yet tested for iodine allergy; iodine anaphylaxis or angioedema; HIGH CREATININE or blood urea nitrogen (renally cleared, NEPHROTOXIC); suspected THYROID dysfunction.","s":6},{"t":"Magnetic resonance precautions","d":"Metal implants that are NOT titanium; gadolinium allergy (rare); claustrophobia.","s":6},{"t":"Planes","d":"TRANSVERSE (axial) = cross-section; FRONTAL (coronal) = both lungs, apex to base; SAGITTAL = one side in profile. A slice, not a stacked shadow.","s":7},{"t":"Attenuation","d":"HIGH (bright): bone (very high), FRESH blood, contrast. LOW (dark): air and gas, fluid, coagulated blood. NORMAL: heart and muscle.","s":7},{"t":"Angiogram pearls","d":"DESCENDING AORTA always on the LEFT of the patient's vertebral column; patient's left = YOUR right; RIGHT ventricle nearest the sternum; LEFT ventricle has the thickest wall; for an embolism the PULMONARY ARTERIES matter most.","s":7},{"t":"Clot","d":"A dark filling defect inside a bright, contrast-filled pulmonary artery.","s":7},{"t":"Vasculogram","d":"Almost always a computed tomography angiogram: embolism, pulmonary hypertension, vasculitis, scleroderma.","s":7},{"t":"Pneumonia","d":"CONSOLIDATION (infiltrate): white, filled-in lung where it should be dark. Don't sort bacterial from viral on the film.","s":8},{"t":"★ Pleural effusion","d":"BLUNTED costophrenic angles; on computed tomography a gray collection compressing the lung.","s":8},{"t":"★ Pulmonary edema","d":"CEPHALIZATION of vessels, KERLEY B LINES (short horizontal lines at the outer lower lungs from thickened INTERLOBULAR SEPTA), pleural effusion, INCREASED cardiothoracic ratio.","s":8},{"t":"Pneumothorax","d":"JET BLACK air with the COMPRESSED lung beside it.","s":8},{"t":"★ Interstitial lung disease","d":"Diffuse abnormal patterns in the INTERSTITIUM, not the air sacs. Computed tomography: reticular (net-like), nodular (dots), HONEYCOMBING (cysts 3 to 10 millimeters), volume loss, traction bronchiectasis, GROUND-GLASS (hazy, pale), Kerley B lines.","s":8}],"map":{"principles-of-diagnostic-medicine-i-exam-4-pulmonary-imaging-quiz-version-2":[39,33,51,20,20,21,11,27,25,50,-1,43,14,35,46,52,9,45,34,17,48,45,13,5,49,34,10,36,32,29],"principles-of-diagnostic-medicine-i-exam-4-pulmonary-imaging-quiz":[29,36,52,6,34,24,-1,13,20,15,29,14,22,4,33,11,48,51,35,45,12,49,30,50,38,39,41,26,16,43]}};
